import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.full_like(bins, -np.inf, dtype=float)
    fit = (rem >= 0)
    if not np.any(fit):
        return scores
    max_cap = np.max(bins) if len(bins) > 0 else 1.0
    empty = (bins == max_cap) & fit
    non_empty = fit & ~empty
    if np.any(non_empty):
        scores[non_empty] = 1.0 / (1.0 + rem[non_empty])
    if np.any(empty):
        first_empty_idx = np.argmax(empty)
        best_ne_score = np.max(scores[non_empty]) if np.any(non_empty) else -1.0
        if best_ne_score > 0.5:
            scores[first_empty_idx] = 0.1
        else:
            scores[first_empty_idx] = 0.0
    return scores
```

